def comps(g,val=None):
    from collections import deque
    h,w=g.shape; seen=np.zeros_like(g,bool); res=[]
    for r in range(h):
        for c in range(w):
            if g[r,c] and not seen[r,c]:
                q=deque([(r,c)]); seen[r,c]=True; comp=[]
                while q:
                    a,b=q.popleft(); comp.append((a,b))
                    for dr in(-1,0,1):
                        for dc in(-1,0,1):
                            x,y=a+dr,b+dc
                            if 0<=x<h and 0<=y<w and g[x,y]==g[a,b] and not seen[x,y]:
                                seen[x,y]=True; q.append((x,y))
                res.append((int(g[comp[0][0],comp[0][1]]),tuple(sorted(comp))))
    return res
