# Careful per-band inventory via connected components on whole input grids (no box artifacts):
def cc(g,val):
    from collections import deque
    g=np.array(g); h,w=g.shape; seen=np.zeros((h,w),bool); res=[]
    for r in range(h):
        for c in range(w):
            if g[r,c]==val and not seen[r,c]:
                q=deque([(r,c)]); seen[r,c]=True; comp=[]
                while q:
                    a,b=q.popleft(); comp.append((a,b))
                    for dr in(-1,0,1):
                        for dc in(-1,0,1):
                            x,y=a+dr,b+dc
                            if 0<=x<h and 0<=y<w and g[x,y]==val and not seen[x,y]:
                                seen[x,y]=True; q.append((x,y))
                res.append(comp)
    return res
